    renderer_digest=hashlib.sha256((Path(__file__).resolve().parents[1]/'public/assets/game-3d.js').read_bytes()).hexdigest()[:12]
    body=body.replace('__RENDERER__','/assets/game-3d.js?v='+renderer_digest).replace('25 species','34 species').replace('0 / 25','0 / 34').replace('/ 25 species','/ 34 species')
    body += '<template id="career-map-art">'+(Path(__file__).resolve().parents[1]/'src/maps/world.svg').read_text()+'</template>'
    body += '<script id="career-data" type="application/json">'+json.dumps(career_data(),ensure_ascii=False).replace('<','\\u003c')+'</script>'
    add('/play/','Cast & Catch 2.0: A 3D Fishing Adventure | Castward','Six beautiful waters, a world career, and one more cast. Play a free fishing game with daily challenges, a 60-second tournament, and a collectible Fish Log.',body,'game')
    def asset(name):
        digest=hashlib.sha256((Path(__file__).resolve().parents[1]/'public/assets'/name).read_bytes()).hexdigest()[:12]
        return '/assets/'+name+'?v='+digest
    pages['/play/']['atlasAssets']='<link rel="stylesheet" href="'+asset('game.css')+'">'+''.join('<script src="'+asset(name)+'" defer></script>' for name in ['game-engine.js','game-action.js','game-art.js','game-career.js','game-expedition.js','game.js'])
